const escapeHtml = value => String(value).replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);

export function renderStimulus(stimulus) {
  if (!stimulus) return '';
  const caption = escapeHtml(stimulus.caption || 'Question diagram');
  if (stimulus.type === 'image') return `<figure class="diagram probability-diagram"><img src="${escapeHtml(stimulus.src)}" width="480" height="210" alt="${escapeHtml(stimulus.alt || '')}">${stimulus.caption ? `<figcaption>${caption}</figcaption>` : ''}</figure>`;
  if (stimulus.type === 'html') return stimulus.html;
  if (stimulus.type === 'table') {
    const heads = stimulus.headers.map(value => `<th scope="col">${escapeHtml(value)}</th>`).join('');
    const rows = stimulus.rows.map(row => `<tr class="${row[0] === 'Total' ? 'total' : ''}"><th scope="row">${escapeHtml(row[0])}</th>${row.slice(1).map(value => `<td>${escapeHtml(typeof value === 'number' ? value.toLocaleString('en-US') : value)}</td>`).join('')}</tr>`).join('');
    return `<div class="table-scroll" tabindex="0" role="region" aria-label="${caption}"><table><caption>${caption}</caption><thead><tr>${heads}</tr></thead><tbody>${rows}</tbody></table></div>`;
  }
  if (stimulus.type === 'segmented') {
    const legend = stimulus.legend || ['Indoor', 'Outdoor'];
    const axis = stimulus.axis_label || 'Percent within group';
    const lines = Array.from({ length: 11 }, (_, index) => { const percent = index * 10; const x = 100 + 4.8 * percent; return `<line x1="${x}" y1="38" x2="${x}" y2="149" stroke="#d9dce2"/><text x="${x}" y="170" text-anchor="middle" font-size="12">${percent}%</text>`; }).join('');
    const groups = stimulus.groups.map((group, index) => { const y = 50 + 56 * index; const width = group.values[0] * 480; return `<text x="88" y="${y + 22}" text-anchor="end" font-size="14">${escapeHtml(group.label)}</text><rect x="100" y="${y}" width="${width}" height="34" fill="#444b55"/><rect x="${100 + width}" y="${y}" width="${480 - width}" height="34" fill="#d4d8de"/><rect x="100" y="${y}" width="480" height="34" fill="none" stroke="#444b55"/>`; }).join('');
    return `<figure class="diagram"><figcaption>${caption}</figcaption><svg viewBox="0 30 600 200" role="img" aria-label="${escapeHtml(stimulus.alt || stimulus.caption)}"><title>${caption}</title><desc>${escapeHtml(stimulus.desc || '')}</desc>${lines}${groups}<text x="340" y="195" text-anchor="middle" font-size="13">${escapeHtml(axis)}</text><rect x="205" y="207" width="285" height="22" rx="3" fill="white" stroke="#bcc3cc"/><rect x="215" y="213" width="12" height="10" fill="#444b55"/><text x="233" y="222" font-size="12">${escapeHtml(legend[0])}</text><rect x="350" y="213" width="12" height="10" fill="#d4d8de" stroke="#a8afb9"/><text x="368" y="222" font-size="12">${escapeHtml(legend[1])}</text></svg></figure>`;
  }
  if (stimulus.type === 'simulation_histogram') {
    const grid = Array.from({ length: 6 }, (_, index) => { const y = 220 - 36 * index; return `<line x1="65" y1="${y}" x2="605" y2="${y}" stroke="#d9dce2"/><text x="57" y="${y + 4}" text-anchor="end" font-size="12">${(index / 10).toFixed(1)}</text>`; }).join('');
    const bars = stimulus.counts.map((count, index) => { const value = count / stimulus.trials; const x = 76 + 86 * index; const height = value * 360; return `<rect x="${x}" y="${220 - height}" width="86" height="${height}" fill="#8f99a8" stroke="#444b55"/><text x="${x + 43}" y="${210 - height}" text-anchor="middle" font-size="13">${value.toFixed(3)}</text><text x="${x + 43}" y="239" text-anchor="middle" font-size="13">${index}</text>`; }).join('');
    return `<figure class="diagram"><figcaption>${caption}</figcaption><svg viewBox="0 24 612 252" role="img" aria-label="${caption}"><title>${caption}</title><desc>${escapeHtml(stimulus.desc || '')}</desc>${grid}${bars}<path d="M65 28 V220 H605" fill="none" stroke="#444b55"/><text x="335" y="249" text-anchor="middle" font-size="13">${escapeHtml(stimulus.axis_label || '')}</text><text transform="translate(16 130) rotate(-90)" text-anchor="middle" font-size="13">Relative frequency</text></svg></figure>`;
  }
  if (stimulus.type === 'venn') return `<figure class="diagram"><figcaption>${caption}</figcaption><svg viewBox="8 4 484 254" role="img" aria-label="Travel-to-work Venn diagram"><rect x="12" y="8" width="476" height="246" rx="10" fill="#fafbfc" stroke="#aeb8c4"/><circle cx="190" cy="130" r="88" fill="#55708b" fill-opacity=".12" stroke="#52667d" stroke-width="2"/><circle cx="294" cy="130" r="88" fill="#55708b" fill-opacity=".12" stroke="#52667d" stroke-width="2"/><g font-size="16" text-anchor="middle"><text x="155" y="30">Cycled</text><text x="331" y="30">Walked</text><text x="150" y="136">36</text><text x="242" y="136">12</text><text x="334" y="136">24</text></g><text x="412" y="229" font-size="15" text-anchor="middle">28 neither</text></svg></figure>`;
  if (stimulus.type === 'tree') return `<figure class="diagram"><figcaption>${caption}</figcaption><svg viewBox="4 12 575 266" role="img" aria-label="Parcel probability tree"><g stroke="#99a5b5" stroke-width="2" fill="none"><path d="M45 145 L235 75 M45 145 L235 215 M305 75 L495 28 M305 75 L495 120 M305 215 L495 175 M305 215 L495 262"/></g><g font-size="15" fill="#28374a"><text x="12" y="168">Parcel</text><text x="90" y="83">0.30</text><text x="90" y="218">0.70</text><text x="240" y="79">Express</text><text x="240" y="220">Standard</text><text x="380" y="35">0.90</text><text x="380" y="122">0.10</text><text x="380" y="173">0.60</text><text x="380" y="264">0.40</text><text x="505" y="34">On time</text><text x="505" y="126">Late</text><text x="505" y="181">On time</text><text x="505" y="268">Late</text></g></svg></figure>`;
  return '';
}
